-- Date-effective assignments are derived from existing history; deployment does not rewrite business rows.
create function public.vehicle_assignment_day(p_value text)returns date language plpgsql immutable set search_path=''as $$declare d date;begin if nullif(btrim(p_value),'')is null then return null;end if;if left(p_value,10)!~'^\d{4}-\d{2}-\d{2}$'then return null;end if;begin d:=left(p_value,10)::date;exception when others then return null;end;return d;end;$$;
create function public.vehicle_assignment_history(p_vehicle jsonb)returns jsonb language plpgsql immutable set search_path=''as $$declare h jsonb:=p_vehicle->'driver_history';begin if h is null or h='null'::jsonb then return '[]'::jsonb;end if;if jsonb_typeof(h)='string'then begin h:=(h#>>'{}')::jsonb;exception when others then return null;end;end if;if jsonb_typeof(h)<>'array'then return null;end if;return h;end;$$;
create function public.vehicle_assignment_has_history(p_vehicle jsonb)returns boolean language sql immutable set search_path=''as $$select public.vehicle_assignment_history(p_vehicle)is null or exists(select 1 from jsonb_array_elements(public.vehicle_assignment_history(p_vehicle))h where nullif(btrim(coalesce(nullif(h->>'driver_id',''),h->>'driver_name','')),'')is not null)$$;
create function public.vehicle_assignment_matches(p_record jsonb,p_driver uuid)returns boolean language sql stable security definer set search_path=''as $$select case when nullif(btrim(p_record->>'driver_id'),'')is not null then p_record->>'driver_id'=p_driver::text else exists(select 1 from public.drivers d where d.id=p_driver and d.name=btrim(p_record->>'driver_name')and(select count(*)from public.drivers x where x.name=d.name)=1)end$$;
create function public.vehicle_assignment_records(p_vehicle jsonb,p_day date)returns jsonb language plpgsql stable security definer set search_path=''as $$declare h jsonb:=public.vehicle_assignment_history(p_vehicle);r jsonb:='[]';name text;begin
 if public.vehicle_assignment_has_history(p_vehicle)then return coalesce((select jsonb_agg(x)from jsonb_array_elements(h)x where nullif(btrim(coalesce(nullif(x->>'driver_id',''),x->>'driver_name','')),'')is not null and(coalesce(x->>'start_at','')=''or public.vehicle_assignment_day(x->>'start_at')<=p_day)and(coalesce(x->>'end_at','')=''or public.vehicle_assignment_day(x->>'end_at')>=p_day)),'[]'::jsonb);end if;
 if nullif(p_vehicle->>'current_driver_id','')is not null then r:=r||jsonb_build_array(jsonb_build_object('driver_id',p_vehicle->>'current_driver_id','driver_name',coalesce((select d.name from public.drivers d where d.id::text=p_vehicle->>'current_driver_id'),'')));end if;
 foreach name in array string_to_array(coalesce(p_vehicle->>'assigned_driver_names',''),'/')loop if btrim(name)<>''and not exists(select 1 from jsonb_array_elements(r)x where x->>'driver_name'=btrim(name))then r:=r||jsonb_build_array(jsonb_build_object('driver_name',btrim(name)));end if;end loop;return r;end;$$;
create function public.driver_vehicle_links(p_day date)returns table(driver_id uuid,vehicle_id uuid,plate_no text,model text)language sql stable security definer set search_path=''as $$select distinct d.id,v.id,v.plate_no,coalesce(to_jsonb(v)->>'model','')from public.vehicles v cross join lateral jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_day))h join public.drivers d on (case when nullif(btrim(h->>'driver_id'),'')is not null then h->>'driver_id'=d.id::text else btrim(h->>'driver_name')=d.name and(select count(*)from public.drivers dx where dx.name=d.name)=1 end)$$;
create function public.vehicle_assignment_stamp(p_vehicle jsonb)returns text language sql immutable set search_path=''as $$select md5(jsonb_build_object('history',p_vehicle->'driver_history','driver',p_vehicle->'current_driver_id','names',p_vehicle->'assigned_driver_names')::text)$$;
create function public.vehicle_assignment_seed(p_vehicle jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$declare h jsonb:=public.vehicle_assignment_history(p_vehicle);begin if h is null then raise exception '駕駛紀錄格式異常，請先核對；未修改資料';end if;if public.vehicle_assignment_has_history(p_vehicle)then return h;end if;return h||public.vehicle_assignment_records(p_vehicle,(statement_timestamp()at time zone 'Asia/Taipei')::date);end;$$;
create table public.vehicle_change_jobs(id uuid primary key,driver_id uuid not null references public.drivers(id),target_vehicle_id uuid not null references public.vehicles(id),effective_on date not null,mode text not null check(mode in('replace','share')),until_on date,status text not null default 'scheduled'check(status in('scheduled','cancelled')),reason text not null default '',actor jsonb not null,request_shape jsonb not null,before_rows jsonb not null,after_rows jsonb not null,revision integer not null default 1,created_at timestamptz not null default clock_timestamp(),cancelled_at timestamptz,cancelled_by jsonb,cancel_reason text);
create unique index vehicle_change_driver_day on public.vehicle_change_jobs(driver_id,effective_on)where status='scheduled';alter table public.vehicle_change_jobs enable row level security;revoke all on public.vehicle_change_jobs from public,anon,authenticated;
create function public.vehicle_change_preview(p_driver uuid,p_target uuid,p_on date,p_mode text)returns jsonb language plpgsql security definer set search_path=''as $$declare d public.drivers;target public.vehicles;affected jsonb;next_day date;begin
 if p_on is null or p_on<=(statement_timestamp()at time zone 'Asia/Taipei')::date or p_mode not in('replace','share')then raise exception '請選擇未來生效日期與接替／共用方式';end if;
 select * into d from public.drivers where id=p_driver and btrim(driver_status)in('待上線','跑趟中');if not found then raise exception '請選擇待上線或跑趟中的司機';end if;
 select * into target from public.vehicles where id=p_target;if not found or coalesce(to_jsonb(target)->>'status','')='報廢'or coalesce(to_jsonb(target)->>'lease_status','')in('出售','已出售')then raise exception '請選擇可用車輛';end if;
 if exists(select 1 from public.vehicle_change_jobs where driver_id=p_driver and effective_on=p_on and status='scheduled')then raise exception '該司機此日已有換車安排，請先取消或核對';end if;
 if exists(select 1 from public.vehicles v cross join lateral jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_on))h where v.id<>p_target and public.vehicle_assignment_matches(h,p_driver)and public.vehicle_assignment_day(h->>'start_at')=p_on)then raise exception '此日已有駕駛交接紀錄，請先核對原安排';end if;
 if p_mode='replace'and exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(target),p_on))h where not public.vehicle_assignment_matches(h,p_driver)and public.vehicle_assignment_day(h->>'start_at')=p_on)then raise exception '目標車此日已有交接，請先核對或選擇共用';end if;
 select min(day)into next_day from(select public.vehicle_assignment_day(h->>'start_at')as day from public.vehicles v cross join lateral jsonb_array_elements(public.vehicle_assignment_history(to_jsonb(v)))h where(public.vehicle_assignment_matches(h,p_driver)or(p_mode='replace'and v.id=p_target))and public.vehicle_assignment_day(h->>'start_at')>p_on)s;
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'plate_no',v.plate_no,'stamp',public.vehicle_assignment_stamp(to_jsonb(v)),'drivers',coalesce((select jsonb_agg(distinct x.name)from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_on))h join public.drivers x on public.vehicle_assignment_matches(h,x.id)),'[]'::jsonb))order by v.plate_no),'[]'::jsonb)into affected from public.vehicles v where v.id=p_target or exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_on))h where public.vehicle_assignment_matches(h,p_driver));
 if not exists(select 1 from public.vehicles v where v.id<>p_target and exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_on))h where public.vehicle_assignment_matches(h,p_driver)))and exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(target),p_on))h where public.vehicle_assignment_matches(h,p_driver))and(p_mode='share'or jsonb_array_length(public.vehicle_assignment_records(to_jsonb(target),p_on))=1)then raise exception '指定日期已使用此車，無須重複安排';end if;
 return jsonb_build_object('driver_id',d.id,'driver_name',d.name,'target_id',target.id,'plate_no',target.plate_no,'effective_on',p_on,'mode',p_mode,'until_on',next_day-1,'affected',affected);end;$$;
create function public.save_vehicle_change(p_id uuid,p_driver uuid,p_target uuid,p_on date,p_mode text,p_versions jsonb,p_reason text,p_actor jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare job public.vehicle_change_jobs;preview jsonb;v public.vehicles;h jsonb;r jsonb;next_h jsonb;before_rows jsonb:='[]';after_rows jsonb:='[]';shape jsonb:=jsonb_build_object('driver',p_driver,'target',p_target,'day',p_on,'mode',p_mode,'reason',coalesce(p_reason,''));begin
 if p_id is null or length(coalesce(p_reason,''))>500 or jsonb_typeof(p_versions)is distinct from 'array'then raise exception '請先預覽換車安排';end if;
 perform pg_advisory_xact_lock(hashtextextended('vehicle-assignment-plans',0));select * into job from public.vehicle_change_jobs where id=p_id;
 if found then if job.request_shape is distinct from shape or job.actor->>'id'is distinct from p_actor->>'id'then raise exception '操作編號已使用，請重新預覽';end if;return jsonb_build_object('job',to_jsonb(job),'replayed',true);end if;
 lock table public.vehicles in share row exclusive mode;
 preview:=public.vehicle_change_preview(p_driver,p_target,p_on,p_mode);
 if jsonb_array_length(p_versions)<>jsonb_array_length(preview->'affected')or exists(select 1 from jsonb_array_elements(preview->'affected')a where not exists(select 1 from jsonb_array_elements(p_versions)e where e->>'id'=a->>'id'and e->>'stamp'=a->>'stamp'))then raise exception '駕駛指派已變動，未儲存，請重新預覽';end if;
 for v in select * from public.vehicles where id in(select(a->>'id')::uuid from jsonb_array_elements(preview->'affected')a)order by id for update loop
  before_rows:=before_rows||jsonb_build_array(jsonb_build_object('id',v.id,'plate_no',v.plate_no,'history',v.driver_history,'sql_null',v.driver_history is null,'stamp',public.vehicle_assignment_stamp(to_jsonb(v))));
  h:=public.vehicle_assignment_seed(to_jsonb(v));next_h:='[]';
  for r in select x from jsonb_array_elements(h)x loop
   if exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(jsonb_build_object('driver_history',jsonb_build_array(r)),p_on))a)and((v.id<>p_target and public.vehicle_assignment_matches(r,p_driver))or(v.id=p_target and p_mode='replace'and not public.vehicle_assignment_matches(r,p_driver)))then r:=r||jsonb_build_object('end_at',(p_on-1)::text);end if;
   next_h:=next_h||jsonb_build_array(r);
  end loop;
  if v.id=p_target and not exists(select 1 from jsonb_array_elements(public.vehicle_assignment_records(to_jsonb(v),p_on))a where public.vehicle_assignment_matches(a,p_driver))then next_h:=next_h||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'driver_id',p_driver,'driver_name',(select name from public.drivers where id=p_driver),'start_at',p_on::text,'end_at',coalesce(preview->>'until_on',''),'notes','換車安排','change_job_id',p_id));end if;
  update public.vehicles set driver_history=next_h,updated_at=clock_timestamp()where id=v.id returning * into v;
  after_rows:=after_rows||jsonb_build_array(jsonb_build_object('id',v.id,'plate_no',v.plate_no,'history',v.driver_history,'stamp',public.vehicle_assignment_stamp(to_jsonb(v))));
 end loop;
 insert into public.vehicle_change_jobs(id,driver_id,target_vehicle_id,effective_on,mode,until_on,reason,actor,request_shape,before_rows,after_rows)values(p_id,p_driver,p_target,p_on,p_mode,public.vehicle_assignment_day(preview->>'until_on'),coalesce(p_reason,''),p_actor,shape,before_rows,after_rows)returning * into job;
 return jsonb_build_object('job',to_jsonb(job));end;$$;
create function public.cancel_vehicle_change(p_id uuid,p_revision integer,p_reason text,p_actor jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare job public.vehicle_change_jobs;r jsonb;v public.vehicles;begin
 perform pg_advisory_xact_lock(hashtextextended('vehicle-assignment-plans',0));lock table public.vehicles in share row exclusive mode;select * into job from public.vehicle_change_jobs where id=p_id for update;
 if not found or job.revision is distinct from p_revision or job.status<>'scheduled'then raise exception '安排已變動，請重新整理';end if;
 if job.effective_on<=(statement_timestamp()at time zone 'Asia/Taipei')::date then raise exception '安排已生效，不可回灌舊紀錄；請另排換車';end if;
 if nullif(btrim(p_reason),'')is null or length(p_reason)>500 then raise exception '請填寫取消原因（500字內）';end if;
 for r in select x from jsonb_array_elements(job.after_rows)x loop select * into v from public.vehicles where id=(r->>'id')::uuid for update;if public.vehicle_assignment_stamp(to_jsonb(v))is distinct from r->>'stamp'then raise exception '有後續駕駛紀錄變動，未取消；請先取消較後安排或核對';end if;end loop;
 for r in select x from jsonb_array_elements(job.before_rows)x loop update public.vehicles set driver_history=case when(r->>'sql_null')::boolean then null else r->'history'end,updated_at=clock_timestamp()where id=(r->>'id')::uuid;end loop;
 update public.vehicle_change_jobs set status='cancelled',revision=revision+1,cancelled_at=clock_timestamp(),cancelled_by=p_actor,cancel_reason=btrim(p_reason)where id=p_id returning * into job;return to_jsonb(job);end;$$;
create function public.vehicle_change_directory()returns jsonb language sql stable security definer set search_path=''as $$select jsonb_build_object('today',(statement_timestamp()at time zone 'Asia/Taipei')::date,'drivers',coalesce((select jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'status',d.driver_status,'fleet',coalesce(p.name,d.fleet_name))order by(case when p.name='亞菲得股份有限公司'then 0 else 1 end),d.name)from public.drivers d left join public.insurance_partners p on p.id=d.dealer_partner_id where btrim(d.driver_status)in('跑趟中','待上線')),'[]'::jsonb),'vehicles',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'plate_no',v.plate_no,'model',to_jsonb(v)->>'model','brand',to_jsonb(v)->>'brand')order by v.plate_no)from public.vehicles v where coalesce(to_jsonb(v)->>'status','')<>'報廢'and coalesce(to_jsonb(v)->>'lease_status','')not in('出售','已出售')),'[]'::jsonb),'jobs',coalesce((select jsonb_agg(jsonb_build_object('id',j.id,'driver_name',d.name,'plate_no',v.plate_no,'effective_on',j.effective_on,'until_on',j.until_on,'status',j.status,'mode',j.mode,'revision',j.revision)order by j.created_at desc)from(select * from public.vehicle_change_jobs order by created_at desc limit 50)j join public.drivers d on d.id=j.driver_id join public.vehicles v on v.id=j.target_vehicle_id),'[]'::jsonb))$$;
-- Eligibility is status-based even before a first assignment/login, retaining dealer permission boundaries.
create or replace function public.driver_reporting_dealer(p_driver uuid)returns uuid language sql stable security definer set search_path=''as $$select min(p.id::text)::uuid from public.drivers d join public.insurance_partners p on(case when d.dealer_partner_id is not null then p.id=d.dealer_partner_id else p.name=d.fleet_name end)where d.id=p_driver and btrim(d.driver_status)in('跑趟中','待上線')and p.name='亞菲得股份有限公司'and p.partner_type='dealer'and p.active=true and coalesce(p.frontend_permissions->'driverReporting'='true'::jsonb,p.name='亞菲得股份有限公司')having count(*)=1$$;
create or replace function public.driver_roster_vehicles()returns jsonb language sql stable security definer set search_path=''as $$with current_links as(select * from public.driver_vehicle_links((statement_timestamp()at time zone 'Asia/Taipei')::date)),future_links as(select distinct d.id as driver_id,v.id as vehicle_id,v.plate_no,coalesce(to_jsonb(v)->>'model','')as model,public.vehicle_assignment_day(h->>'start_at')as effective_on from public.vehicles v cross join lateral jsonb_array_elements(public.vehicle_assignment_history(to_jsonb(v)))h join public.drivers d on (case when nullif(btrim(h->>'driver_id'),'')is not null then h->>'driver_id'=d.id::text else btrim(h->>'driver_name')=d.name and(select count(*)from public.drivers dx where dx.name=d.name)=1 end)where public.vehicle_assignment_day(h->>'start_at')>(statement_timestamp()at time zone 'Asia/Taipei')::date and not exists(select 1 from current_links c where c.driver_id=d.id)),upcoming as(select * from future_links f where effective_on=(select min(x.effective_on)from future_links x where x.driver_id=f.driver_id))select coalesce(jsonb_agg(to_jsonb(x)order by x.plate_no),'[]'::jsonb)from(select driver_id,vehicle_id,plate_no,model,false as upcoming,null::date as effective_on from current_links union all select driver_id,vehicle_id,plate_no,model,true,effective_on from upcoming)x$$;
create function public.driver_roster_vehicle_changes(p_month date)returns jsonb language sql stable security definer set search_path=''as $$
with records as materialized(select distinct d.id as driver_id,v.plate_no,public.vehicle_assignment_day(h->>'start_at')as starts_on,public.vehicle_assignment_day(h->>'end_at')as ends_on from public.vehicles v cross join lateral jsonb_array_elements(case when public.vehicle_assignment_has_history(to_jsonb(v))then public.vehicle_assignment_history(to_jsonb(v))else public.vehicle_assignment_records(to_jsonb(v),(statement_timestamp()at time zone 'Asia/Taipei')::date)end)h join public.drivers d on (case when nullif(btrim(h->>'driver_id'),'')is not null then h->>'driver_id'=d.id::text else btrim(h->>'driver_name')=d.name and(select count(*)from public.drivers dx where dx.name=d.name)=1 end) where(coalesce(h->>'start_at','')=''or public.vehicle_assignment_day(h->>'start_at')is not null)and(coalesce(h->>'end_at','')=''or public.vehicle_assignment_day(h->>'end_at')is not null)),boundaries as(select distinct driver_id,day from records cross join lateral(values(starts_on),(ends_on+1))b(day)where day>=p_month and day<(p_month+interval '1 month')),states as(select b.driver_id,b.day,coalesce((select jsonb_agg(distinct r.plate_no order by r.plate_no)from records r where r.driver_id=b.driver_id and(r.starts_on is null or r.starts_on<=b.day-1)and(r.ends_on is null or r.ends_on>=b.day-1)),'[]'::jsonb)as before_plates,coalesce((select jsonb_agg(distinct r.plate_no order by r.plate_no)from records r where r.driver_id=b.driver_id and(r.starts_on is null or r.starts_on<=b.day)and(r.ends_on is null or r.ends_on>=b.day)),'[]'::jsonb)as after_plates from boundaries b)select coalesce(jsonb_agg(jsonb_build_object('driver_id',driver_id,'date',day,'before_plates',before_plates,'after_plates',after_plates)order by day,driver_id),'[]'::jsonb)from states where before_plates is distinct from after_plates$$;
create or replace function public.driver_roster_details(p_month date)returns jsonb language sql stable security definer set search_path=''as $$select public.driver_roster_load(p_month)||jsonb_build_object('profiles',coalesce((select jsonb_agg(to_jsonb(p))from public.driver_roster_profiles p),'[]'::jsonb),'vehicle_changes',public.driver_roster_vehicle_changes(p_month))$$;
create function public.driver_vehicle_snapshot(p_driver uuid,p_known text default null)returns jsonb language plpgsql stable security definer set search_path=''as $$declare vehicles jsonb;stamp text;day date:=(statement_timestamp()at time zone 'Asia/Taipei')::date;begin
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'plate_no',v.plate_no,'brand',to_jsonb(v)->'brand','model',to_jsonb(v)->'model','status',to_jsonb(v)->'status','current_driver_id',v.current_driver_id,'assigned_driver_names',v.assigned_driver_names,'driver_history',v.driver_history,'fleet_name',to_jsonb(v)->'fleet_name','vehicle_region',to_jsonb(v)->'vehicle_region','fuel_type',to_jsonb(v)->'fuel_type','registration_doc_url',to_jsonb(v)->'registration_doc_url','registration_doc_name',to_jsonb(v)->'registration_doc_name','vehicle_files',to_jsonb(v)->'vehicle_files','roadside_assistance_phone',to_jsonb(v)->'roadside_assistance_phone','compulsory_insurance_company',to_jsonb(v)->'compulsory_insurance_company','voluntary_insurance_company',to_jsonb(v)->'voluntary_insurance_company','insurance_company',to_jsonb(v)->'insurance_company','dealer_partner_id',to_jsonb(v)->'dealer_partner_id','compulsory_insurance_expiry',to_jsonb(v)->'compulsory_insurance_expiry','voluntary_insurance_expiry',to_jsonb(v)->'voluntary_insurance_expiry','next_inspection_date',to_jsonb(v)->'next_inspection_date')order by v.plate_no),'[]'::jsonb)into vehicles from public.vehicles v where v.id in(select x.vehicle_id from public.driver_vehicle_links(day)x where x.driver_id=p_driver);
 stamp:=md5(day::text||vehicles::text);if p_known=stamp then return jsonb_build_object('stamp',stamp,'day',day,'unchanged',true);end if;return jsonb_build_object('vehicles',vehicles,'stamp',stamp,'day',day,'unchanged',false);end;$$;
-- Recompute a small stamp when assignment history/status changes, without polling document blobs.
create or replace function public.driver_roster_stamp(p_month date)returns text language sql stable security definer set search_path=''as $$select md5(coalesce(string_agg(value,'|'order by value),''))from(
select 'r:'||id::text||':'||revision::text as value from public.driver_reporting_submissions where month=p_month
union all select 'n:'||driver_id::text||':'||work_on::text||':'||revision::text from public.driver_roster_notes where work_on>=p_month and work_on<(p_month+interval '1 month')
union all select 's:'||driver_id::text||':'||revision::text from public.driver_roster_shifts where month=p_month
union all select 'p:'||driver_id::text||':'||revision::text from public.driver_roster_profiles
union all select 'd:'||id::text||':'||coalesce(to_jsonb(d)->>'region','')||':'||coalesce(driver_status,'')||':'||coalesce(dealer_partner_id::text,'')||':'||coalesce(fleet_name,'')from public.drivers d
union all select 'v:'||(statement_timestamp()at time zone 'Asia/Taipei')::date::text||':'||md5(jsonb_build_object('id',v.id,'assignment',public.vehicle_assignment_stamp(to_jsonb(v)),'model',to_jsonb(v)->>'model')::text)from public.vehicles v
union all select 'c:'||md5(to_jsonb(c)::text)from public.calendar_events c where event_date>=p_month and event_date<(p_month+interval '1 month')and event_type in('maintenance','repair','tires'))s$$;

revoke all on function public.vehicle_assignment_day(text) from public,anon,authenticated;grant execute on function public.vehicle_assignment_day(text) to service_role;
revoke all on function public.vehicle_assignment_history(jsonb) from public,anon,authenticated;grant execute on function public.vehicle_assignment_history(jsonb) to service_role;
revoke all on function public.vehicle_assignment_has_history(jsonb) from public,anon,authenticated;grant execute on function public.vehicle_assignment_has_history(jsonb) to service_role;
revoke all on function public.vehicle_assignment_matches(jsonb,uuid) from public,anon,authenticated;grant execute on function public.vehicle_assignment_matches(jsonb,uuid) to service_role;
revoke all on function public.vehicle_assignment_records(jsonb,date) from public,anon,authenticated;grant execute on function public.vehicle_assignment_records(jsonb,date) to service_role;
