-- Back office includes active/waiting Yafeide drivers; driver self-service keeps dealer gating.
create function public.driver_reporting_admin_allowed(p_driver uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.drivers d join public.insurance_partners p on(case when d.dealer_partner_id is not null then p.id=d.dealer_partner_id else p.name=d.fleet_name end)where d.id=p_driver and btrim(d.driver_status)in('待上線','跑趟中')and p.name='亞菲得股份有限公司'and p.partner_type='dealer'and p.active=true)$$;
revoke all on function public.driver_reporting_admin_allowed(uuid) from public,anon,authenticated;grant execute on function public.driver_reporting_admin_allowed(uuid) to service_role;
create or replace function public.driver_reporting_load(p_month date, p_driver uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare result jsonb; begin
  if p_month is null or extract(day from p_month) <> 1 then raise exception '月份格式錯誤'; end if;
  if p_driver is not null and public.driver_reporting_dealer(p_driver) is null then raise exception '所屬車商尚未開放司機報班'; end if;
  select jsonb_build_object(
    'month',p_month,'server_today',(clock_timestamp() at time zone 'Asia/Taipei')::date,
    'config',(select to_jsonb(m) from public.driver_reporting_months m where m.month=p_month),
    'months',coalesce((select jsonb_agg(to_char(m.month,'YYYY-MM') order by m.month desc)
      from public.driver_reporting_months m where p_driver is null or m.is_open
      or exists(select 1 from public.driver_reporting_submissions s where s.month=m.month and s.driver_id=p_driver)),'[]'),
    'rows',coalesce((select jsonb_agg(jsonb_build_object(
      'driver_id',d.id,'driver_name',d.name,'driver_status',d.driver_status,'dealer_name',coalesce(p.name,nullif(d.fleet_name,''),s.dealer_name,'未設定車商'),'dealer_id',p.id,
      'submission',case when s.id is null then null else to_jsonb(s) end) order by d.name,d.id)
      from public.drivers d
      left join public.insurance_partners p on(case when d.dealer_partner_id is not null then p.id=d.dealer_partner_id else p.name=d.fleet_name and(select count(*)from public.insurance_partners pp where pp.name=d.fleet_name)=1 end)
      left join public.driver_reporting_submissions s on s.driver_id=d.id and s.month=p_month
      where((p_driver is null and public.driver_reporting_admin_allowed(d.id))or d.id=p_driver)),'[]'),
    'audit',case when p_driver is null then coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc,a.id desc)
      from (select * from public.driver_reporting_audit where month=p_month order by created_at desc,id desc limit 100) a),'[]') else '[]'::jsonb end
  ) into result;
  return result;
end; $$;
create or replace function public.driver_roster_shift_save(p_month date,p_driver uuid,p_label text,p_revision integer,p_actor jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare previous public.driver_roster_shifts;saved public.driver_roster_shifts;begin
 if p_month is null or extract(day from p_month)<>1 or p_revision is null or p_revision<0 or length(coalesce(p_label,''))>40 or not public.driver_reporting_admin_allowed(p_driver) then raise exception '請確認月份、班別與可報班司機';end if;
 perform pg_advisory_xact_lock(hashtextextended('driver-shift:'||p_month::text||p_driver::text,0));
 select * into previous from public.driver_roster_shifts where month=p_month and driver_id=p_driver for update;
 if coalesce(previous.revision,0)<>p_revision then raise exception '班別已更新，請重新整理';end if;
 insert into public.driver_roster_shifts(month,driver_id,shift_label,revision,updated_by)values(p_month,p_driver,trim(coalesce(p_label,'')),p_revision+1,p_actor)on conflict(month,driver_id)do update set shift_label=excluded.shift_label,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp()returning * into saved;
 insert into public.driver_roster_shift_audit(month,driver_id,before_data,after_data,actor)values(p_month,p_driver,to_jsonb(previous),to_jsonb(saved),p_actor);return to_jsonb(saved);end;$$;
create or replace function public.driver_reporting_admin_set(p_month date,p_driver uuid,p_dates date[],p_revision bigint,p_note text,p_actor jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare saved public.driver_reporting_submissions;cfg public.driver_reporting_months;d public.drivers;dealer public.insurance_partners;day date;begin
 if p_month is null or extract(day from p_month)<>1 or p_revision is null or p_revision<0 or not public.driver_reporting_admin_allowed(p_driver) then raise exception '請確認月份與可報班司機';end if;
 if p_dates is null or cardinality(p_dates)>31 or cardinality(p_dates)<>(select count(distinct x)from unnest(p_dates)x)or array_position(p_dates,null)is not null then raise exception '休假日期不可重複、空白或超過31天';end if;
 foreach day in array p_dates loop if day<p_month or day>=(p_month+interval '1 month')::date then raise exception '只能編輯該月份的休假日期';end if;end loop;
 if length(coalesce(p_note,''))>1000 then raise exception '修改備註最多1000字';end if;
 perform pg_advisory_xact_lock(hashtextextended('driver-reporting:'||p_month::text,0));
 select * into saved from public.driver_reporting_submissions where month=p_month and driver_id=p_driver for update;
 if found then return public.driver_reporting_admin_edit(saved.id,p_dates,p_revision,p_note,p_actor);end if;
 if p_revision<>0 then raise exception '報班已更新，請重新整理';end if;
 select * into cfg from public.driver_reporting_months where month=p_month for update;
 if not found then
  insert into public.driver_reporting_months(month,is_open,opens_on,closes_on,allowed_days)values(p_month,false,p_month,p_month,4)returning * into cfg;
  insert into public.driver_reporting_audit(month,actor,action,details)values(p_month,p_actor,'month_settings',jsonb_build_object('after',to_jsonb(cfg),'reason','後台安排休假，月份仍未開放'));
 end if;
 select * into d from public.drivers where id=p_driver;select * into dealer from public.insurance_partners where id=d.dealer_partner_id or(d.dealer_partner_id is null and name=d.fleet_name)order by id limit 1;
 insert into public.driver_reporting_submissions(month,driver_id,driver_name,dealer_name,off_dates,allowed_days,range_rules,status,reviewed_at,reviewer_name,admin_edited_at,admin_editor_name,admin_edit_note)
 values(p_month,p_driver,d.name,coalesce(dealer.name,nullif(d.fleet_name,''),'未設定車商'),array(select x from unnest(p_dates)x order by x),cfg.allowed_days,cfg.range_rules,'approved',clock_timestamp(),p_actor->>'name',clock_timestamp(),p_actor->>'name',coalesce(p_note,''))returning * into saved;
 insert into public.driver_reporting_audit(month,submission_id,actor,action,details)values(p_month,saved.id,p_actor,'admin_created',jsonb_build_object('before',null,'after',to_jsonb(saved),'reason',coalesce(p_note,''),'constraints_overridden',true));return to_jsonb(saved);end;$$;
create or replace function public.driver_roster_profile_save(p_driver uuid,p_location text,p_revision integer,p_actor jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare previous public.driver_roster_profiles;saved public.driver_roster_profiles;begin
 if p_location is null or length(p_location)>80 or p_revision is null or p_revision<0 or not public.driver_reporting_admin_allowed(p_driver) then raise exception '請確認可報班司機與位置';end if;
 perform pg_advisory_xact_lock(hashtextextended('roster-profile:'||p_driver::text,0));select * into previous from public.driver_roster_profiles where driver_id=p_driver for update;
 if coalesce(previous.revision,0)<>p_revision then raise exception '司機位置已更新，請重新整理';end if;
 insert into public.driver_roster_profiles(driver_id,location,revision,updated_by)values(p_driver,btrim(p_location),p_revision+1,p_actor)on conflict(driver_id)do update set location=excluded.location,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp()returning * into saved;
 insert into public.driver_roster_profile_audit(driver_id,before_data,after_data,actor)values(p_driver,to_jsonb(previous),to_jsonb(saved),p_actor);return to_jsonb(saved);end;$$;
create or replace function public.driver_roster_cells_save(p_month date,p_cells jsonb,p_actor jsonb)returns jsonb language plpgsql security definer set search_path=''as $$
declare cell record;person record;saved public.driver_reporting_submissions;dates date[];current_rev integer;result jsonb;begin
 if p_month is null or extract(day from p_month)<>1 or jsonb_typeof(p_cells)is distinct from 'array'or jsonb_array_length(p_cells)not between 1 and 200 then raise exception '請選擇同月份1至200個格子';end if;
 if exists(select 1 from jsonb_to_recordset(p_cells)as c(driver_id uuid,work_on date,note text,color text,note_revision integer,leave_day boolean,leave_revision bigint)where c.driver_id is null or c.work_on is null or c.work_on<p_month or c.work_on>=(p_month+interval '1 month')or c.note is null or length(c.note)>1000 or c.color is null or (c.color<>''and c.color!~'^#[0-9a-fA-F]{6}$')or c.note_revision is null or c.note_revision<0 or (c.leave_day is not null and(c.leave_revision is null or c.leave_revision<0))or not public.driver_reporting_admin_allowed(c.driver_id))then raise exception '格子格式或司機不正確';end if;
 if(select count(*)from(select distinct c->>'driver_id',c->>'work_on'from jsonb_array_elements(p_cells)c)s)<>jsonb_array_length(p_cells)then raise exception '不可重複編輯同一格';end if;
 perform pg_advisory_xact_lock(hashtextextended('driver-reporting:'||p_month::text,0));
 for cell in select * from jsonb_to_recordset(p_cells)as c(driver_id uuid,work_on date,note text,color text,note_revision integer,leave_day boolean,leave_revision bigint)order by driver_id,work_on loop
  perform pg_advisory_xact_lock(hashtextextended(cell.driver_id::text||cell.work_on::text,0));select revision into current_rev from public.driver_roster_notes where driver_id=cell.driver_id and work_on=cell.work_on for update;
  if coalesce(current_rev,0)<>cell.note_revision then raise exception '格子已被更新，整批未儲存，請重新整理';end if;
 end loop;
 for person in select driver_id,min(leave_revision)as expected,count(distinct leave_revision)as versions from jsonb_to_recordset(p_cells)as c(driver_id uuid,leave_day boolean,leave_revision bigint)where leave_day is not null group by driver_id order by driver_id loop
  select * into saved from public.driver_reporting_submissions where month=p_month and driver_id=person.driver_id for update;
  if person.versions<>1 or coalesce(saved.revision,0)<>person.expected then raise exception '休假已更新，整批未儲存，請重新整理';end if;
  if saved.status='rejected'and exists(select 1 from jsonb_array_elements(p_cells)c where(c->>'driver_id')::uuid=person.driver_id and(c->>'leave_day')::boolean is true)then raise exception '此司機報班已被退回，請先重新審核再安排休假';end if;
  select array(select distinct x from unnest(coalesce(saved.off_dates,'{}')||array(select(c->>'work_on')::date from jsonb_array_elements(p_cells)c where(c->>'driver_id')::uuid=person.driver_id and(c->>'leave_day')::boolean is true))x where x<>all(array(select(c->>'work_on')::date from jsonb_array_elements(p_cells)c where(c->>'driver_id')::uuid=person.driver_id and(c->>'leave_day')::boolean is false))order by x)into dates;
  if(saved.id is null and cardinality(dates)=0)or(saved.id is not null and dates is not distinct from saved.off_dates)then continue;end if;
  result:=public.driver_reporting_admin_set(p_month,person.driver_id,dates,person.expected,'班表快速編輯',p_actor);
 end loop;
 for cell in select * from jsonb_to_recordset(p_cells)as c(driver_id uuid,work_on date,note text,color text,note_revision integer)order by driver_id,work_on loop
  result:=public.driver_roster_save_color(cell.driver_id,cell.work_on,cell.note,cell.color,cell.note_revision,p_actor);
 end loop;return jsonb_build_object('saved',jsonb_array_length(p_cells));end;$$;
notify pgrst,'reload schema';
